// Вкладка «Друзья»: поиск по нику GitHub, состояния, список, каталог друга, публичный каталог в настройках.
// Запуск: node design/prototype/friends-tab.test.js [shots]
const {chromium}=require('playwright');const path=require('path');
const IDX='file://'+path.join(__dirname,'index.html');const OUT=path.join(__dirname,'..','screenshots')+'/';const shots=process.argv[2]==='shots';
(async()=>{const b=await chromium.launch();let fails=0;
const V=[['ПК 1440×900',{viewport:{width:1440,height:900}},''],['телефон 390×844',{viewport:{width:390,height:844},isMobile:true,hasTouch:true},'phone-']];
for(const th of (shots?['dark','light']:['dark']))for(const [vn,o,k] of V){const ctx=await b.newContext({...o,colorScheme:th});const p=await ctx.newPage();const errs=[];p.on('pageerror',e=>errs.push(e.message));
 const ev=(f,a)=>p.evaluate(f,a);
 const click=async s=>{const l=p.locator(s).first();if(o.hasTouch)await l.tap({timeout:3000});else await l.click({timeout:3000});await p.waitForTimeout(250)};
 const sel=async(id,v)=>{await ev(([id,v])=>{const s=document.querySelector('#'+id);s.value=v;s.dispatchEvent(new Event('change',{bubbles:true}))},[id,v]);await p.waitForTimeout(300)};
 const go=async h=>{await ev(()=>{location.hash='search'});await p.waitForTimeout(120);await ev(h=>{location.hash=h},h);await p.waitForTimeout(350)};
 const shot=async n=>{await ev(()=>document.querySelectorAll('.toast').forEach(t=>t.remove()));if(shots)await p.screenshot({path:OUT+n+'-'+k+th+'.png'})};
 const find=async q=>{await p.locator('#frq').fill(q);await p.press('#frq','Enter');await p.waitForTimeout(150)};
 const txt=s=>ev(s=>(document.querySelector(s)||{}).textContent||'',s);
 const noHscroll=()=>ev(()=>document.documentElement.scrollWidth<=innerWidth&&document.querySelector('#main').scrollWidth<=document.querySelector('#main').clientWidth);
 const res=[];const T=async(n,f)=>{try{res.push([n,(await f())?'OK':'FAIL'])}catch(e){res.push([n,'FAIL '+e.message.split('\n')[0].slice(0,80)])}};
 await p.goto(IDX+'#catalog');await p.waitForTimeout(500);
 await T('Пункт «Друзья» между «Списками» и «Поиском»',async()=>{const n=await ev(()=>[...document.querySelectorAll('#rail a span')].map(s=>s.textContent).filter(Boolean));return n.indexOf('Друзья')===n.indexOf('Списки')+1&&n.indexOf('Поиск')===n.indexOf('Друзья')+1&&await ev(()=>(s=>s.scrollWidth<=s.parentElement.clientWidth+1)([...document.querySelectorAll('#rail a span')].find(s=>s.textContent==='Друзья')))});
 await T('Экран «Друзья»: поле поиска и список с аватаром и счётчиками',async()=>{await click('#rail a[href="#friends"]');await p.waitForTimeout(200);await shot('250-friends-list');return await ev(()=>document.querySelector('#frq').placeholder==='Найти друга по нику GitHub'&&document.querySelectorAll('.fr-list .fcard').length===2&&[...document.querySelectorAll('.fr-list .fcard')].every(c=>c.querySelector('.avatar')&&/смотрю \d+/.test(c.textContent)&&/просмотрено \d+/.test(c.textContent)&&/понравилось \d+/.test(c.textContent)))&&await noHscroll()});
 await T('Поиск: «Ищем @…», потом карточка с «Добавить в друзья»',async()=>{await find('kenji-lists');const busy=/Ищем @kenji-lists/.test(await txt('#frres'));await shot('251-friends-searching');await p.waitForTimeout(900);await shot('252-friends-found');return busy&&/Кэндзи/.test(await txt('#frres'))&&/10 тайтлов/.test(await txt('#frres'))&&!!await ev(()=>document.querySelector('#frres [data-fradd]'))&&await noHscroll()});
 await T('«Добавить в друзья» → в списке 3',async()=>{await click('#frres [data-fradd]');return await ev(()=>document.querySelectorAll('.fr-list .fcard').length===3)});
 await T('Нет публичного каталога',async()=>{await find('private-user');await p.waitForTimeout(900);await shot('253-friends-no-public');return /нет публичного каталога/.test(await txt('#frres'))});
 await T('Лимит поиска',async()=>{await find('limit');await p.waitForTimeout(900);await shot('254-friends-limit');return /Лимит поиска GitHub исчерпан/.test(await txt('#frres'))});
 await T('Не найден',async()=>{await find('nobody-xyz');await p.waitForTimeout(900);return /нет пользователя @nobody-xyz/.test(await txt('#frres'))});
 await T('Каталог друга: «Каталог Мика · обновлено …», 6 вкладок',async()=>{await click('.fr-list a[data-friend="mika-anime"]');await p.waitForTimeout(250);await shot('255-friend-catalog');return /Каталог Мика/.test(await txt('.fr-head h1'))&&/обновлено 2 часа назад/.test(await txt('.fr-head'))&&(await ev(()=>[...document.querySelectorAll('[data-frtab]')].map(b=>b.firstChild.nodeType===3?b.childNodes[0].textContent:b.textContent.replace(/\d+$/,'')).join('|')))==='Смотрю|Просмотрено|В планах|Брошено|Понравилось|Заметки'&&await ev(()=>document.querySelectorAll('.grid .card').length===3)&&await noHscroll()});
 await T('«Понравилось» друга',async()=>{await click('[data-frtab=FAV]');return await ev(()=>document.querySelectorAll('.grid .card').length===3)});
 await T('Заметки друга: вердикт, итог, моменты',async()=>{await click('[data-frtab=NOTES]');await shot('256-friend-notes');return await ev(()=>{const n=[...document.querySelectorAll('.fnote')];return n.length===3&&n.every(x=>x.querySelector('.vchip')&&x.querySelector('.sum'))&&/1 эп\. · 05:12/.test(n[0].textContent)})});
 await T('«Удалить из друзей» с подтверждением',async()=>{await click('[data-frdel]');await shot('257-friend-remove-dialog');const dlg=/Удалить Мика из друзей\?/.test(await txt('#dialog'));await click('[data-frdelok]');await p.waitForTimeout(300);return dlg&&await ev(()=>location.hash==='#friends'&&![...document.querySelectorAll('.fr-list .fcard')].some(c=>/Мика/.test(c.textContent)))});
 await T('Пусто: «Пока нет друзей»',async()=>{await sel('demoFriends','empty');await shot('258-friends-empty');const ok=/Пока нет друзей/.test(await txt('.state'));await sel('demoFriends','ok');return ok});
 await T('Без входа: «Войдите через GitHub, чтобы искать друзей»',async()=>{await ev(()=>{prof().gh=null;prof().sync='out';document.querySelector('#demoSync').value='out'});await go('friends');await shot('259-friends-signed-out');const ok=/Войдите через GitHub, чтобы искать друзей/.test(await txt('.fr-res'))&&await ev(()=>!document.querySelector('#frq'));await ev(()=>{prof().gh='yuki-dev';prof().sync='ok';document.querySelector('#demoSync').value='ok'});return ok});
 await T('Настройки: «Открыть каталог» → диалог с публичным текстом',async()=>{await go('settings');await ev(()=>document.querySelector('#pubrow').scrollIntoView({block:'center'}));await click('[data-act=pubOn]');await shot('260-settings-public-dialog');return /Ваш каталог станет виден всем, кто найдёт вас по нику GitHub/.test(await txt('#dialog'))});
 await T('Каталог открыт: «включён» и отдельная кнопка «Отключить публичный каталог»',async()=>{await click('[data-act=pubOnOk]');await ev(()=>document.querySelector('#pubrow').scrollIntoView({block:'center'}));await shot('261-settings-public-on');return /включён/.test(await txt('#pubrow'))&&/Отключить публичный каталог/.test(await txt('#pubrow [data-act=pubOff]'))});
 await T('«Отключить публичный каталог» с подтверждением',async()=>{await click('[data-act=pubOff]');const ok=/Публичный Gist с каталогом будет удалён/.test(await txt('#dialog'));await click('[data-act=pubOffOk]');return ok&&!!await ev(()=>document.querySelector('[data-act=pubOn]'))});
 const bad=res.filter(r=>r[1]!=='OK');fails+=bad.length;console.log(th,vn,bad.length?bad:'все '+res.length+' OK',errs);await ctx.close();}
await b.close();process.exitCode=fails?1:0;})();
